+    <div class="score-badge" aria-label="${score} out of ${total} correct">${score} / ${total}</div>
+    <p style="color:var(--text-muted);font-size:.9rem">${pct}% — ${remark(pct)}</p>
+    <ul class="result-list" role="list">${itemsHtml}</ul>`;
+}
+
+function remark(pct) {
+  if (pct === 100) return "Perfect score! 🎉";
+  if (pct >= 66)  return "Well done!";
+  if (pct >= 33)  return "Keep studying!";
+  return "Better luck next time.";
+}
+
+function escapeHtml(str) {
+  return str
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;");
+}
+
+// ── Mount ─────────────────────────────────────────────────────────────────────
+function mountQuiz() {
+  const form = document.getElementById("quiz-form");
+
+  // Render question cards
+  const cardsHtml = QUESTIONS.map((q, i) =>
+    QuestionCard({ id: q.id, index: i, text: q.text, helpText: q.helpText, options: q.options })
+  ).join("");
+  form.insertAdjacentHTML("afterbegin", cardsHtml);
+
+  // ── Submit handler ──────────────────────────────────────────────────────────
+  form.addEventListener("submit", (e) => {
+    e.preventDefault();
+
+    let firstInvalid = null;
+    let allValid = true;
+
+    const details = QUESTIONS.map((q) => {
+      const checked = [...form.querySelectorAll(`input[name="${q.id}"]:checked`)]
+        .map(el => el.value);
+      const errorEl = document.getElementById(`${q.id}-error`);
+
+      // Validate: at least one selection
+      if (checked.length === 0) {
+        errorEl.hidden = false;
+        allValid = false;
+        if (!firstInvalid) firstInvalid = form.querySelector(`input[name="${q.id}"]`);
+      } else {
+        errorEl.hidden = true;
+      }
+
+      // Grade
+      const selectedSet  = new Set(checked);
+      const isCorrect    = setsEqual(selectedSet, q.correct);
+      const correctLabels = q.options
+        .filter(o => q.correct.has(o.value))
+        .map(o => o.label);
+      const selectedLabels = q.options
+        .filter(o => selectedSet.has(o.value))
+        .map(o => o.label);
+
+      return { text: q.text, isCorrect, correctLabels, selectedLabels };
+    });
+
+    if (!allValid) {
+      firstInvalid.focus();
+      return;
+    }
+
+    const score = details.filter(d => d.isCorrect).length;
+
+    // Render results
+    const resultsEl = document.getElementById("results");
+    resultsEl.innerHTML = ResultsPanel({ score, total: QUESTIONS.length, details });
+    resultsEl.hidden = false;
+    resultsEl.focus();
+    resultsEl.scrollIntoView({ behavior: "smooth", block: "start" });
+  });
+}
+
+function setsEqual(a, b) {
+  if (a.size !== b.size) return false;
+  for (const v of a) if (!b.has(v)) return false;
+  return true;
+}
+
+document.addEventListener("DOMContentLoaded", mountQuiz);
+
')

