  --border:       #2e3350;
  --border-hover: #4a5080;
  --accent:       #6c7fff;
  --accent-light: #8fa3ff;
  --btn-bg:       #3d52d0;   /* darker blue — 5.6:1 on white, passes AA */
  --btn-bg-hover: #4a5ee0;
  --accent-glow:  rgba(108,127,255,.25);
  --text:         #e2e4f0;
  --text-muted:   #8b90aa;
  --text-dim:     #5a5f78;
  --success:      #4ade80;
  --success-bg:   rgba(74,222,128,.12);
  --error:        #f87171;
  --error-bg:     rgba(248,113,113,.12);
  --focus-ring:   #6c7fff;
  --radius:       10px;
  --radius-sm:    6px;
  --transition:   180ms ease;
}

html { font-size: 16px; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

/* ── Skip link ───────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Layout ──────────────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.page-header h1 {
  font-size: clamp(1.6rem, 4vw, 2.4rem);
  font-weight: 700;
  letter-spacing: -.03em;
  background: linear-gradient(135deg, var(--accent-light) 0%, #c084fc 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.page-header p {
  margin-top: .5rem;
  color: var(--text-muted);
  font-size: .95rem;
}

main {
  max-width: 660px;
  margin: 0 auto;
}

/* ── Quiz form ───────────────────────────────────────────────── */
#quiz-form { display: flex; flex-direction: column; gap: 1.5rem; }

/* ── form-field (question card) ─────────────────────────────── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  transition: border-color var(--transition);
}
.form-field:focus-within { border-color: var(--border-hover); }

/* Remove default fieldset styling */
.form-field fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.form-field legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: .25rem;
  width: 100%;
  line-height: 1.4;
}

.question-number {
  display: inline-block;
  background: var(--accent-glow);
  color: var(--accent-light);
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .15rem .5rem;
  border-radius: 4px;
  margin-bottom: .6rem;
}

.help-text {
  font-size: .85rem;
  color: var(--text-muted);
  margin-top: .35rem;
  margin-bottom: 1rem;
}

.error-text {
  font-size: .85rem;
  color: var(--error);
  margin-top: .5rem;
  display: flex;
  align-items: center;
  gap: .35rem;
}
.error-text[hidden] { display: none; }

/* ── Options list ─────────────────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: .55rem;
  margin-top: .75rem;
  list-style: none;
}

.option-item {
  display: flex;
  align-items: center;
}

/* Hide native checkbox visually, keep it accessible */
.option-item input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
  cursor: pointer;
}

.option-item label {
  display: flex;
  align-items: center;
  gap: .75rem;
  cursor: pointer;
  font-size: .95rem;
  color: var(--text);
  padding: .6rem .85rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  width: 100%;
  background: var(--surface-2);
  transition: border-color var(--transition), background var(--transition);
  user-select: none;
}
.option-item label:hover {
  border-color: var(--border-hover);
  background: #262b40;
}

/* Custom checkbox box */
.option-item label::before {
  content: "";
  flex-shrink: 0;
  width: 1.1rem;
  height: 1.1rem;
  border: 2px solid var(--border-hover);
  border-radius: 4px;
  background: var(--surface);
  transition: border-color var(--transition), background var(--transition);
}

/* Checked state */
.option-item input[type="checkbox"]:checked + label {
  border-color: var(--accent);
  background: rgba(108,127,255,.08);
  color: var(--accent-light);
}
.option-item input[type="checkbox"]:checked + label::before {
  background: var(--accent);
  border-color: var(--accent);
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 12 10' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 5l3.5 3.5L11 1' stroke='%23fff' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: center;
  background-size: 70%;
}

/* Focus-visible ring on the label */
.option-item input[type="checkbox"]:focus-visible + label {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

/* ── Submit button ────────────────────────────────────────────── */
.submit-wrap {
  display: flex;
  justify-content: flex-end;
  margin-top: .5rem;
}

button[type="submit"] {
  background: var(--btn-bg);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  padding: .75rem 2rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  letter-spacing: .01em;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
button[type="submit"]:hover {
  background: var(--btn-bg-hover);
  box-shadow: 0 0 0 6px var(--accent-glow);
}
button[type="submit"]:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 3px;
}
button[type="submit"]:active { transform: scale(.97); }

/* ── Results panel ────────────────────────────────────────────── */
#results {
  margin-top: 2rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
}
#results[hidden] { display: none; }

#results h2 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.score-badge {
  display: inline-block;
  font-size: 2rem;
  font-weight: 800;
  background: linear-gradient(135deg, var(--accent-light), #c084fc);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: .75rem;
}

.result-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  margin-top: .75rem;
}

.result-item {
  font-size: .9rem;
  padding: .6rem .85rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: flex-start;
  gap: .5rem;
}
.result-item.correct {
  background: var(--success-bg);
  color: var(--success);
  border: 1px solid rgba(74,222,128,.25);
}
.result-item.incorrect {
  background: var(--error-bg);
  color: var(--error);
  border: 1px solid rgba(248,113,113,.25);
}
.result-item .icon { flex-shrink: 0; font-style: normal; }

.result-answer {
  color: var(--text-muted);
  font-size: .82rem;
  margin-top: .15rem;
}

/* ── Forced colors (Windows HC) ─────────────────────────────── */
@media (forced-colors: active) {
  .option-item label::before { border: 2px solid ButtonText; background: Field; }
  .option-item input[type="checkbox"]:checked + label::before {
    background: Highlight;
    border-color: Highlight;
    forced-color-adjust: none;
  }
  button[type="submit"] { forced-color-adjust: none; }
}

